def add_rule(
        style_sheet_id: dom.StyleSheetId,
        rule_text: str,
        location: SourceRange,
        node_for_property_syntax_validation: dom.NodeId | None = None,
) -> typing.Generator[T_JSON_DICT, T_JSON_DICT, CSSRule]:
    '''Inserts a new rule with the given `ruleText` in a stylesheet with given `styleSheetId`, at the
    position specified by `location`.

    :param style_sheet_id: The css style sheet identifier where a new rule should be inserted.
    :param rule_text: The text of a new rule.
    :param location: Text position of a new rule in the target style sheet.
    :param node_for_property_syntax_validation: *(Optional)* NodeId for the DOM node in whose context custom property declarations for registered properties should be validated. If omitted, declarations in the new rule text can only be validated statically, which may produce incorrect results if the declaration contains a var() for example. *(EXPERIMENTAL)*
    :returns: The newly created rule.
    '''
    params: T_JSON_DICT = {}
    params['styleSheetId'] = style_sheet_id.to_json()
    params['ruleText'] = rule_text
    params['location'] = location.to_json()
    if node_for_property_syntax_validation is not None:
        params['nodeForPropertySyntaxValidation'] = node_for_property_syntax_validation.to_json()
    json = yield {'method': 'CSS.addRule', 'params': params}
    return CSSRule.from_json(json['rule'])


