        [CSSKeyframesRule.from_json(i) for i in json['cssKeyframesRules']] if json.get('cssKeyframesRules') is not None else None,
        [CSSPositionTryRule.from_json(i) for i in json['cssPositionTryRules']] if json.get('cssPositionTryRules') is not None else None,
        json['activePositionFallbackIndex'] if json.get('activePositionFallbackIndex') is not None else None,
        [CSSPropertyRule.from_json(i) for i in json['cssPropertyRules']] if json.get('cssPropertyRules') is not None else None,
        [CSSPropertyRegistration.from_json(i) for i in json['cssPropertyRegistrations']] if json.get('cssPropertyRegistrations') is not None else None,
        [CSSAtRule.from_json(i) for i in json['cssAtRules']] if json.get('cssAtRules') is not None else None,
        dom.NodeId.from_json(json['parentLayoutNodeId']) if json.get('parentLayoutNodeId') is not None else None,
