def set_style_texts(
        edits: list[StyleDeclarationEdit],
        node_for_property_syntax_validation: dom.NodeId | None = None,
) -> typing.Generator[T_JSON_DICT, T_JSON_DICT, list[CSSStyle]]:
    '''Applies specified style edits one after another in the given order.

    :param edits:
    :param node_for_property_syntax_validation: *(Optional)* NodeId for the DOM node in whose context custom property declarations for registered properties should be validated. If omitted, declarations in the new rule text can only be validated statically, which may produce incorrect results if the declaration contains a var() for example. *(EXPERIMENTAL)*
    :returns: The resulting styles after modification.
    '''
    params: T_JSON_DICT = {}
    params['edits'] = [i.to_json() for i in edits]
    if node_for_property_syntax_validation is not None:
        params['nodeForPropertySyntaxValidation'] = node_for_property_syntax_validation.to_json()
    json = yield {'method': 'CSS.setStyleTexts', 'params': params}
    return [CSSStyle.from_json(i) for i in json['styles']]


def start_rule_usage_tracking() -> typing.Generator[T_JSON_DICT, T_JSON_DICT, None]:
    '''Enables the selector recording.'''
    yield {'method': 'CSS.startRuleUsageTracking'}


def stop_rule_usage_tracking() -> typing.Generator[T_JSON_DICT, T_JSON_DICT, list[RuleUsage]]:
    '''Stop tracking rule usage and return the list of rules that were used since last call to
    `takeCoverageDelta` (or since start of coverage instrumentation).

    :returns:
    '''
    json = yield {'method': 'CSS.stopRuleUsageTracking'}
    return [RuleUsage.from_json(i) for i in json['ruleUsage']]


def take_coverage_delta() -> typing.Generator[T_JSON_DICT, T_JSON_DICT, tuple[list[RuleUsage], float]]:
    '''Obtain list of rules that became used since last call to this method (or since start of coverage
    instrumentation).

    :returns: A tuple with the following items:
        0. **coverage** —
        1. **timestamp** — Monotonically increasing time, in seconds.
    '''
    json = yield {'method': 'CSS.takeCoverageDelta'}
    return (
        [RuleUsage.from_json(i) for i in json['coverage']],
        float(json['timestamp']),
    )


