@event_class('CSS.fontsUpdated')
@dataclass(slots=True)
class FontsUpdated:
    '''Fires whenever a web font is updated.  A non-empty font parameter indicates a successfully loaded
    web font.
    '''
    #: *(Optional)* The web font that has loaded.
    font: FontFace | None = None

    @classmethod
    def from_json(cls, json: T_JSON_DICT) -> FontsUpdated:
        return cls(
            font=FontFace.from_json(json['font']) if json.get('font') is not None else None,
        )


